'use strict';
// Invented business profiles for fictional issuers. Not research about real companies.
const CompanyProfiles = (() => {
  const sectors = {
    'Energy':{models:[['Supplies fuel to factories and transport companies.','Sales of fuel and delivery services.'],['Stores and distributes fuel for commercial customers.','Storage fees and fuel-distribution contracts.'],['Operates energy-production sites.','Sales of the energy produced at its sites.']],watch:'Lower energy prices or production interruptions could reduce the cash available to pay debt.'},
    'Healthcare':{models:[['Operates outpatient clinics and medical centers.','Fees for patient visits, tests and treatments.'],['Provides diagnostic testing for clinics and hospitals.','Payments for laboratory tests and diagnostic services.'],['Runs a network of community health facilities.','Payments from patients and healthcare payers for care provided.']],watch:'Staffing costs, payment delays or changes in reimbursement could put pressure on cash flow.'},
    'Utilities':{models:[['Supplies electricity to homes and businesses.','Customer bills for electricity usage and service.'],['Operates water supply and treatment systems.','Customer water bills and service charges.'],['Maintains water networks for local communities.','Water-service charges paid by customers.']],watch:'Repairs and infrastructure spending can be expensive, while permitted customer charges may limit revenue.'},
    'Technology':{models:[['Builds business software used to manage everyday operations.','Subscription fees paid by business customers.'],['Provides cloud hosting and data services.','Usage charges and hosting subscriptions.'],['Sells software tools to small businesses.','Software subscriptions and support services.']],watch:'Customers could switch providers or cancel subscriptions, while product development still costs money.'},
    'Consumer goods':{models:[['Makes household cleaning and care products.','Sales of products through shops and distributors.'],['Produces everyday personal-care products.','Sales to retailers and wholesale customers.'],['Supplies household essentials to stores.','Sales of branded and store-label products.']],watch:'Higher material costs or weaker customer demand could squeeze the cash earned from each sale.'},
    'Financials':{models:[['Provides loans and financial services to businesses.','Interest on loans and fees for financial services.'],['Finances equipment purchases for commercial customers.','Loan interest and equipment-financing fees.'],['Provides lending services to small businesses.','Interest and fees paid by borrowers.']],watch:'Borrowers may fail to repay, and the company’s own funding costs may rise.'},
    'Industrials':{models:[['Makes equipment used in factories.','Equipment sales and maintenance contracts.'],['Supplies industrial tools and replacement parts.','Sales of tools, parts and related services.'],['Builds machinery for manufacturing businesses.','Machinery sales, repairs and servicing.']],watch:'Customers may delay equipment orders during a slowdown, while factory costs continue.'},
    'Telecommunications':{models:[['Operates broadband networks for households and businesses.','Monthly internet subscriptions and connection fees.'],['Provides mobile and business connectivity services.','Service subscriptions and data-usage charges.'],['Connects offices through communication networks.','Business network contracts and support fees.']],watch:'Network upgrades require cash, and competition may force the company to reduce prices.'},
    'Real estate':{models:[['Owns and rents out apartment buildings.','Rent and related property-service charges.'],['Owns warehouses leased to businesses.','Rent from commercial property leases.'],['Owns and operates neighborhood shopping properties.','Rent and service charges paid by retail tenants.']],watch:'Empty properties, unpaid rent and refinancing costs could reduce the cash available for debt payments.'},
    'Materials':{models:[['Produces metals and building materials.','Sales of materials to manufacturers and builders.'],['Makes chemicals used in manufacturing.','Sales of chemical products to industrial customers.'],['Produces metal alloys for factories.','Sales of alloys and processed metal products.']],watch:'Raw-material and energy costs can change quickly, while customer demand follows industrial activity.'},
    'Transportation':{models:[['Moves goods and operates distribution warehouses.','Freight delivery and warehouse-service fees.'],['Transports freight by rail.','Charges for moving customers’ goods.'],['Operates a commercial trucking network.','Delivery charges and freight-service contracts.']],watch:'Fuel costs, disruptions and lower shipment volumes could reduce earnings.'},
    'Automotive':{models:[['Designs and manufactures passenger vehicles.','Vehicle sales through dealers and other sales channels.'],['Makes replacement parts for vehicles.','Sales to vehicle makers, repair shops and distributors.'],['Manufactures vehicles for commercial fleets.','Vehicle sales and fleet-service contracts.']],watch:'Weaker vehicle demand, recalls or supply shortages could interrupt sales and add costs.'},
    'Retail':{models:[['Runs stores selling everyday household essentials.','Sales to shoppers in stores and online.'],['Operates stores and an online shopping business.','Product sales to retail customers.'],['Runs neighborhood grocery and convenience stores.','Sales of food and everyday essentials.']],watch:'Shoppers may spend less, while rent, wages and unsold stock still cost money.'},
    'Food & beverages':{models:[['Makes packaged food sold in grocery stores.','Sales to supermarkets and food distributors.'],['Produces bottled drinks for shops and restaurants.','Sales of beverages to retail and hospitality customers.'],['Processes grains into food ingredients.','Sales of ingredients to food manufacturers.']],watch:'Ingredient costs, food-safety problems or changing customer demand could hurt sales and margins.'},
    'Media & entertainment':{models:[['Produces and distributes television and digital content.','Content licensing fees and advertising revenue.'],['Produces films and television programs.','Licensing and distribution payments for its productions.'],['Creates entertainment programs for streaming services.','Production contracts and content-licensing fees.']],watch:'Content is costly to produce, and audience demand or licensing income can disappoint.'},
    'Hospitality & leisure':{models:[['Owns and operates hotels.','Room bookings, food and guest-service sales.'],['Operates leisure venues and visitor attractions.','Admission fees and spending by visitors.'],['Runs holiday resorts.','Room bookings and sales of resort services.']],watch:'Travel demand can fall, while property upkeep, staffing and debt payments continue.'},
    'Agriculture':{models:[['Grows and sells agricultural crops.','Crop sales to processors and distributors.'],['Supplies farming equipment and agricultural inputs.','Sales of farm supplies and related services.'],['Produces and distributes seeds to farmers.','Sales of seeds and growing supplies.']],watch:'Weather, crop prices and farmers’ spending can change revenue and operating costs.'},
    'Business services':{models:[['Provides outsourced facilities and office services.','Service fees paid under business contracts.'],['Helps businesses run customer-support operations.','Contract fees for staffed support services.'],['Provides maintenance services to commercial properties.','Maintenance contracts and project fees.']],watch:'Clients may reduce or cancel contracts, while staffing costs can rise.'}
  };
  function attach(bonds,pool){
    const profiles=new Map(),counts={};
    for(const b of bonds){
      const name=b.name.split(' · ')[0];
      if(!profiles.has(name)){
        const sector=sectors[b.sector],row=pool.find(r=>r[0]===b.sector);
        const specified=row?row.slice(1,4).indexOf(name):-1;
        const index=specified>=0?specified:(counts[b.sector]||0)%sector.models.length;
        counts[b.sector]=(counts[b.sector]||0)+1;
        const [business,income]=sector.models[index];
        profiles.set(name,{name,business,income,watch:sector.watch,fictional:true});
      }
      b.company=profiles.get(name);
    }
  }
  return {attach};
})();
